<?php declare(strict_types=1); ?>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Permanent evidence</span><h2>Supplier portal event history</h2></div><span class="panel-meta"><?= count($events) ?> events</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Event</th><th>Entity</th><th>Actor</th><th>Status</th><th>Evidence</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= h(date_us($event['created_at'],true)) ?></td><td><strong><?= h(status_label($event['event_type'])) ?></strong></td><td><?= h(status_label($event['entity_type'])) ?> #<?= (int)$event['entity_id'] ?></td><td><?= h(status_label($event['actor_type'])) ?></td><td><?= h(($event['from_status']??'—').' → '.($event['to_status']??'—')) ?></td><td><?= h($event['evidence_note']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
